SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, COUNT(CASE WHEN i.los BETWEEN 1 AND 2 THEN 1 END) AS los_1_2, COUNT(CASE WHEN i.los BETWEEN 3 AND 5 THEN 1 END) AS los_3_5, COUNT(CASE WHEN i.los BETWEEN 6 AND 9 THEN 1 END) AS los_6_9, COUNT(CASE WHEN i.los >= 10 THEN 1 END) AS los_10_plus, COUNT(CASE WHEN d.diabetes = 1 THEN 1 END) AS diabetes_patients, COUNT(CASE WHEN d.ckd = 1 THEN 1 END) AS ckd_patients, COUNT(CASE WHEN a.admission_type_code = 'STEMICH' THEN 1 END) AS stemi_admissions, COUNT(CASE WHEN a.admission_type_code = 'NSTEMI' THEN 1 END) AS nstemi_admissions FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id LEFT JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 56 AND p.anchor_year BETWEEN 51 AND 61 GROUP BY i.los, d.diabetes, d.ckd;